<script>(function(){var b=document.getElementById('aiads-generate'),f=document.getElementById('aiads-copy-form'),s=document.getElementById('aiads-copy-status');if(!b||!f)return;b.addEventListener('click',function(){var p=document.getElementById('aiads-prompt').value.trim();if(!p){s.textContent='Describe your ad first.';return}b.disabled=true;s.textContent='Generating suggestions…';var data=new URLSearchParams();data.append('<?= html_escape($csrfName); ?>','<?= html_escape($csrfHash); ?>');data.append('prompt',p);data.append('product_id',document.getElementById('aiads-product').value);fetch('<?= base_url('marketing/ai_ads/generate_copy'); ?>',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data.toString(),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'Could not generate copy.');document.getElementById('aiads-headline').value=r.copy.headline;document.getElementById('aiads-body').value=r.copy.body;s.textContent='Review and edit the suggestion before saving.'}).catch(function(e){s.textContent=e.message||'AI copy is unavailable.'}).finally(function(){b.disabled=false})})})();</script>
